from __future__ import annotations

import argparse
import os
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent

# Chaque valeur contient, sans modification, le code source de l'ancien script.
SCRIPTS = {
    'AMMC.py': '"""\r\nScraper AMMC - Collecte des rapports financiers annuels par société\r\n=====================================================================\r\n\r\nCONTEXTE :\r\nLa page "fiche société" de l\'AMMC (ex: /fr/espace-emetteurs/liste-des-emetteurs/2763)\r\nn\'affiche parfois qu\'un historique partiel (ex: Cosumar n\'y montre que 2019-2025).\r\nEn revanche, la liste globale non filtrée :\r\n    https://www.ammc.ma/fr/liste-etats-financiers-emetteurs\r\ncontient un historique plus complet mais paginé sur ~425 pages, toutes sociétés\r\nconfondues, triées par date de publication décroissante.\r\n\r\nCE SCRIPT FAIT DEUX PASSES :\r\n  1) Parcourt les ~425 pages de la liste globale, et garde uniquement les lignes\r\n     dont le nom de société correspond à votre liste cible (COMPANIES ci-dessous).\r\n  2) Pour chaque fiche trouvée à l\'étape 1, va chercher la page de détail\r\n     (ex: cosumar-rfa-2023) pour en extraire le VRAI lien PDF + la taille du\r\n     fichier (ce que l\'on voit dans le tableau "Pièce jointe" de la fiche).\r\n\r\nIMPORTANT :\r\n- Ce script doit être exécuté sur VOTRE machine (avec accès internet à ammc.ma) ;\r\n  l\'environnement sandbox qui a généré ce script n\'a pas accès à ammc.ma.\r\n- Le site AMMC ne bloque pas le scraping via robots.txt (contrairement à\r\n  casablanca-bourse.com), mais restez raisonnable : délai entre requêtes,\r\n  ne pas paralléliser agressivement, User-Agent identifiable.\r\n- Adaptez COMPANIES à la liste exacte des ~16-20 sociétés de votre étude.\r\n  Le nom doit correspondre (même partiellement, la recherche est insensible\r\n  à la casse et fait un "contains") à ce qui apparaît dans la colonne "Emetteur"\r\n  du tableau.\r\n\r\nSORTIE :\r\n  ammc_rapports_bruts.csv      -> étape 1 (liste des fiches trouvées)\r\n  ammc_rapports_detailles.csv  -> étape 2 (avec lien PDF direct + métadonnées)\r\n"""\r\n\r\nimport csv\r\nimport re\r\nimport time\r\nfrom dataclasses import dataclass, asdict\r\n\r\nimport requests\r\nfrom bs4 import BeautifulSoup\r\n\r\n# ----------------------------------------------------------------------------\r\n# CONFIGURATION\r\n# ----------------------------------------------------------------------------\r\n\r\nBASE_URL = "https://www.ammc.ma"\r\nLIST_URL = f"{BASE_URL}/fr/liste-etats-financiers-emetteurs"\r\n\r\n# Liste des sociétés à couvrir (adaptez à votre périmètre exact).\r\n# La correspondance est faite en "contient" (insensible à la casse), donc\r\n# "cosumar" matchera "COSUMAR", "Maroc Telecom" matchera "MAROC TELECOM", etc.\r\nCOMPANIES = [\r\n    "cosumar",\r\n    "maroc telecom",\r\n    "banque centrale populaire",  # BCP\r\n    "attijariwafa bank",\r\n    "managem",\r\n    "lafargeholcim maroc",\r\n    "label vie",\r\n    "ciments du maroc",\r\n    # ... complétez avec vos 16-20 sociétés\r\n]\r\n\r\n# Nombre max de pages à parcourir. La pagination Drupal démarre à page=0.\r\n# D\'après l\'exploration manuelle, il y a ~425 pages (page=0 à page=424 environ).\r\nMAX_PAGES = 425\r\n\r\nHEADERS = {\r\n    "User-Agent": (\r\n        "Mozilla/5.0 (compatible; RechercheAcademique/1.0; "\r\n        "usage stage universitaire, contact: <votre-email>)"\r\n    )\r\n}\r\n\r\nREQUEST_DELAY_SECONDS = 1.5  # politesse envers le serveur AMMC\r\nTIMEOUT = 20\r\n\r\n\r\n@dataclass\r\nclass RapportBrut:\r\n    societe: str\r\n    annee: str\r\n    type_rapport: str\r\n    url_fiche: str\r\n    page_liste: int\r\n\r\n\r\n@dataclass\r\nclass RapportDetaille(RapportBrut):\r\n    url_pdf: str = ""\r\n    nom_fichier: str = ""\r\n    taille_annoncee: str = ""  # ex: "13.82 Mo", tel qu\'affiché par l\'AMMC\r\n\r\n\r\ndef matches_target_company(nom_societe: str) -> bool:\r\n    nom = nom_societe.strip().lower()\r\n    return any(cible.lower() in nom for cible in COMPANIES)\r\n\r\n\r\ndef fetch_page(url: str) -> BeautifulSoup | None:\r\n    try:\r\n        resp = requests.get(url, headers=HEADERS, timeout=TIMEOUT)\r\n        resp.raise_for_status()\r\n        return BeautifulSoup(resp.text, "html.parser")\r\n    except requests.RequestException as e:\r\n        print(f"  [ERREUR] {url} -> {e}")\r\n        return None\r\n\r\n\r\ndef parse_list_page(soup: BeautifulSoup, page_num: int) -> list[RapportBrut]:\r\n    """Extrait les lignes du tableau \'Liste des Etats Financiers\' d\'une page."""\r\n    results = []\r\n    table = soup.find("table")\r\n    if not table:\r\n        return results\r\n\r\n    for row in table.find_all("tr"):\r\n        cells = row.find_all("td")\r\n        if len(cells) < 3:\r\n            continue\r\n\r\n        # Colonne Emetteur : contient un lien vers la fiche + le nom de la société\r\n        cell_emetteur = cells[0] if len(cells) == 3 else cells[1]\r\n        cell_annee = cells[1] if len(cells) == 3 else cells[2]\r\n        cell_type = cells[2] if len(cells) == 3 else cells[3]\r\n\r\n        liens = cell_emetteur.find_all("a")\r\n        if not liens:\r\n            continue\r\n        nom_societe = liens[-1].get_text(strip=True)\r\n\r\n        if not matches_target_company(nom_societe):\r\n            continue\r\n\r\n        lien_type = cell_type.find("a")\r\n        if not lien_type:\r\n            continue\r\n\r\n        url_fiche = lien_type["href"]\r\n        if url_fiche.startswith("/"):\r\n            url_fiche = BASE_URL + url_fiche\r\n\r\n        results.append(\r\n            RapportBrut(\r\n                societe=nom_societe,\r\n                annee=cell_annee.get_text(strip=True),\r\n                type_rapport=lien_type.get_text(strip=True),\r\n                url_fiche=url_fiche,\r\n                page_liste=page_num,\r\n            )\r\n        )\r\n    return results\r\n\r\n\r\ndef step1_crawl_list() -> list[RapportBrut]:\r\n    """Parcourt toutes les pages de la liste globale et filtre par société."""\r\n    all_results: list[RapportBrut] = []\r\n\r\n    for page_num in range(MAX_PAGES):\r\n        url = f"{LIST_URL}?page={page_num}"\r\n        print(f"[Page {page_num}/{MAX_PAGES}] {url}")\r\n\r\n        soup = fetch_page(url)\r\n        if soup is None:\r\n            time.sleep(REQUEST_DELAY_SECONDS)\r\n            continue\r\n\r\n        page_results = parse_list_page(soup, page_num)\r\n        if page_results:\r\n            print(f"  -> {len(page_results)} rapport(s) pertinent(s) trouvé(s)")\r\n            all_results.extend(page_results)\r\n\r\n        time.sleep(REQUEST_DELAY_SECONDS)\r\n\r\n    return all_results\r\n\r\n\r\ndef parse_detail_page(soup: BeautifulSoup) -> dict:\r\n    """Extrait le lien PDF direct + la taille depuis une fiche (ex: cosumar-rfa-2023)."""\r\n    info = {"url_pdf": "", "nom_fichier": "", "taille_annoncee": ""}\r\n\r\n    # Sur ces fiches, la pièce jointe apparaît typiquement comme :\r\n    # "COSUMAR RFA 2023.pdf (13.82 Mo)" avec un lien <a href=".../file.pdf">\r\n    for a in soup.find_all("a", href=True):\r\n        href = a["href"]\r\n        if href.lower().endswith(".pdf"):\r\n            info["url_pdf"] = href if href.startswith("http") else BASE_URL + href\r\n            texte = a.get_text(strip=True)\r\n            info["nom_fichier"] = texte\r\n            # Cherche un motif "(xx.xx Mo)" ou "(xx Ko)" dans le texte alentour\r\n            parent_text = a.parent.get_text(" ", strip=True) if a.parent else texte\r\n            taille_match = re.search(r"\\(([\\d.,]+\\s?(?:Mo|Ko|Go))\\)", parent_text)\r\n            if taille_match:\r\n                info["taille_annoncee"] = taille_match.group(1)\r\n            break  # on prend le premier PDF trouvé sur la fiche\r\n\r\n    return info\r\n\r\n\r\ndef step2_enrich_with_pdf_links(rapports: list[RapportBrut]) -> list[RapportDetaille]:\r\n    """Va chercher, pour chaque fiche trouvée, le lien PDF + métadonnées."""\r\n    enriched = []\r\n\r\n    for i, r in enumerate(rapports, 1):\r\n        print(f"[{i}/{len(rapports)}] Détail : {r.societe} - {r.annee} - {r.url_fiche}")\r\n        soup = fetch_page(r.url_fiche)\r\n        detail_info = parse_detail_page(soup) if soup else {}\r\n\r\n        enriched.append(\r\n            RapportDetaille(\r\n                **asdict(r),\r\n                url_pdf=detail_info.get("url_pdf", ""),\r\n                nom_fichier=detail_info.get("nom_fichier", ""),\r\n                taille_annoncee=detail_info.get("taille_annoncee", ""),\r\n            )\r\n        )\r\n        time.sleep(REQUEST_DELAY_SECONDS)\r\n\r\n    return enriched\r\n\r\n\r\ndef save_csv(rows: list, path: str):\r\n    if not rows:\r\n        print(f"Rien à sauvegarder dans {path}")\r\n        return\r\n    fieldnames = list(asdict(rows[0]).keys())\r\n    with open(path, "w", newline="", encoding="utf-8") as f:\r\n        writer = csv.DictWriter(f, fieldnames=fieldnames)\r\n        writer.writeheader()\r\n        for row in rows:\r\n            writer.writerow(asdict(row))\r\n    print(f"-> {len(rows)} lignes écrites dans {path}")\r\n\r\n\r\ndef main():\r\n    print("=== Étape 1 : parcours de la liste globale AMMC ===")\r\n    rapports_bruts = step1_crawl_list()\r\n    save_csv(rapports_bruts, "ammc_rapports_bruts.csv")\r\n\r\n    if not rapports_bruts:\r\n        print("Aucun rapport trouvé pour les sociétés ciblées. Vérifiez COMPANIES.")\r\n        return\r\n\r\n    print("\\n=== Étape 2 : récupération des liens PDF directs ===")\r\n    rapports_detailles = step2_enrich_with_pdf_links(rapports_bruts)\r\n    save_csv(rapports_detailles, "ammc_rapports_detailles.csv")\r\n\r\n    print("\\nTerminé. Vérifiez ammc_rapports_detailles.csv")\r\n\r\n\r\nif __name__ == "__main__":\r\n    main()',
    'main.py': 'from __future__ import annotations\r\n\r\nimport subprocess\r\nimport sys\r\nfrom pathlib import Path\r\nfrom typing import Final\r\n\r\n\r\n# ============================================================\r\n# CONFIGURATION\r\n# ============================================================\r\n\r\nPROJECT_DIR: Final[Path] = Path(__file__).resolve().parent\r\n\r\nSCRIPTS: Final[list[tuple[str, str]]] = [\r\n    (\r\n        "01_find_company_websites.py",\r\n        "Recherche des sites officiels des sociétés",\r\n    ),\r\n    (\r\n        "02_download_reports.py",\r\n        "Recherche et téléchargement des rapports annuels",\r\n    ),\r\n    (\r\n        "03_extract_financials.py",\r\n        "Extraction des données financières depuis les PDF",\r\n    ),\r\n    (\r\n        "04_build_dataset.py",\r\n        "Construction de la base de données finale",\r\n    ),\r\n]\r\n\r\n\r\n# ============================================================\r\n# FONCTIONS\r\n# ============================================================\r\n\r\ndef print_separator() -> None:\r\n    """Affiche une ligne de séparation."""\r\n    print("=" * 70)\r\n\r\n\r\ndef check_python_version() -> None:\r\n    """Vérifie que Python 3.10 ou une version plus récente est utilisé."""\r\n    minimum_version = (3, 10)\r\n\r\n    if sys.version_info < minimum_version:\r\n        raise RuntimeError(\r\n            "Python 3.10 ou une version plus récente est nécessaire.\\n"\r\n            f"Version actuelle : {sys.version}"\r\n        )\r\n\r\n\r\ndef check_required_files() -> None:\r\n    """Vérifie que tous les scripts nécessaires existent."""\r\n    missing_files: list[str] = []\r\n\r\n    for script_name, _ in SCRIPTS:\r\n        script_path = PROJECT_DIR / script_name\r\n\r\n        if not script_path.exists():\r\n            missing_files.append(script_name)\r\n\r\n    if missing_files:\r\n        missing_text = "\\n".join(f"- {name}" for name in missing_files)\r\n\r\n        raise FileNotFoundError(\r\n            "Les fichiers suivants sont absents du dossier du projet :\\n"\r\n            f"{missing_text}\\n\\n"\r\n            "Place tous les scripts dans le même dossier que main.py."\r\n        )\r\n\r\n\r\ndef run_script(script_name: str, description: str) -> None:\r\n    """\r\n    Exécute un script Python et arrête le programme en cas d\'erreur.\r\n    """\r\n    script_path = PROJECT_DIR / script_name\r\n\r\n    print_separator()\r\n    print(f"ÉTAPE : {description}")\r\n    print(f"Fichier : {script_name}")\r\n    print_separator()\r\n\r\n    try:\r\n        subprocess.run(\r\n            [sys.executable, str(script_path)],\r\n            cwd=PROJECT_DIR,\r\n            check=True,\r\n        )\r\n\r\n    except subprocess.CalledProcessError as error:\r\n        print()\r\n        print_separator()\r\n        print("ERREUR")\r\n        print_separator()\r\n        print(f"Le script {script_name} s\'est arrêté avec une erreur.")\r\n        print(f"Code d\'erreur : {error.returncode}")\r\n        print()\r\n        print("Corrige l\'erreur affichée dans le terminal, puis relance main.py.")\r\n\r\n        raise SystemExit(error.returncode) from error\r\n\r\n    except KeyboardInterrupt:\r\n        print()\r\n        print("Exécution interrompue manuellement.")\r\n\r\n        raise SystemExit(130)\r\n\r\n\r\ndef create_project_directories() -> None:\r\n    """Crée les dossiers utilisés par le projet."""\r\n    directories = [\r\n        "data",\r\n        "data/input",\r\n        "data/output",\r\n        "data/intermediate",\r\n        "reports",\r\n        "reports/downloaded",\r\n        "reports/unclassified",\r\n        "logs",\r\n    ]\r\n\r\n    for directory in directories:\r\n        path = PROJECT_DIR / directory\r\n        path.mkdir(parents=True, exist_ok=True)\r\n\r\n\r\ndef main() -> None:\r\n    """Lance toutes les étapes du projet."""\r\n    print()\r\n    print_separator()\r\n    print("AUTOMATISATION DES RAPPORTS FINANCIERS")\r\n    print_separator()\r\n    print(f"Dossier du projet : {PROJECT_DIR}")\r\n    print()\r\n\r\n    check_python_version()\r\n    create_project_directories()\r\n    check_required_files()\r\n\r\n    for script_name, description in SCRIPTS:\r\n        run_script(\r\n            script_name=script_name,\r\n            description=description,\r\n        )\r\n\r\n    print()\r\n    print_separator()\r\n    print("TRAITEMENT TERMINÉ AVEC SUCCÈS")\r\n    print_separator()\r\n    print()\r\n    print("Les résultats se trouvent dans :")\r\n    print(PROJECT_DIR / "data" / "output")\r\n    print()\r\n\r\n\r\nif __name__ == "__main__":\r\n    main()',
    'scraper_ammc.py': '"""\nScraper AMMC - Collecte des rapports financiers annuels par société\n=====================================================================\n\nCONTEXTE :\nLa page "fiche société" de l\'AMMC (ex: /fr/espace-emetteurs/liste-des-emetteurs/2763)\nn\'affiche parfois qu\'un historique partiel (ex: Cosumar n\'y montre que 2019-2025).\nEn revanche, la liste globale non filtrée :\n    https://www.ammc.ma/fr/liste-etats-financiers-emetteurs\ncontient un historique plus complet mais paginé sur ~425 pages, toutes sociétés\nconfondues, triées par date de publication décroissante.\n\nCE SCRIPT FAIT DEUX PASSES :\n  1) Parcourt les ~425 pages de la liste globale, et garde uniquement les lignes\n     dont le nom de société correspond à votre liste cible (COMPANIES ci-dessous).\n  2) Pour chaque fiche trouvée à l\'étape 1, va chercher la page de détail\n     (ex: cosumar-rfa-2023) pour en extraire le VRAI lien PDF + la taille du\n     fichier (ce que l\'on voit dans le tableau "Pièce jointe" de la fiche).\n\nIMPORTANT :\n- Ce script doit être exécuté sur VOTRE machine (avec accès internet à ammc.ma) ;\n  l\'environnement sandbox qui a généré ce script n\'a pas accès à ammc.ma.\n- Le site AMMC ne bloque pas le scraping via robots.txt (contrairement à\n  casablanca-bourse.com), mais restez raisonnable : délai entre requêtes,\n  ne pas paralléliser agressivement, User-Agent identifiable.\n- Adaptez COMPANIES à la liste exacte des ~16-20 sociétés de votre étude.\n  Le nom doit correspondre (même partiellement, la recherche est insensible\n  à la casse et fait un "contains") à ce qui apparaît dans la colonne "Emetteur"\n  du tableau.\n\nSORTIE :\n  ammc_rapports_bruts.csv      -> étape 1 (liste des fiches trouvées)\n  ammc_rapports_detailles.csv  -> étape 2 (avec lien PDF direct + métadonnées)\n"""\n\nimport csv\nimport re\nimport time\nfrom dataclasses import dataclass, asdict\n\nimport requests\nfrom bs4 import BeautifulSoup\n\n# ----------------------------------------------------------------------------\n# CONFIGURATION\n# ----------------------------------------------------------------------------\n\nBASE_URL = "https://www.ammc.ma"\nLIST_URL = f"{BASE_URL}/fr/liste-etats-financiers-emetteurs"\n\n# Liste des sociétés à couvrir (adaptez à votre périmètre exact).\n# La correspondance est faite en "contient" (insensible à la casse), donc\n# "cosumar" matchera "COSUMAR", "Maroc Telecom" matchera "MAROC TELECOM", etc.\nCOMPANIES = [\n    "cosumar",\n    "maroc telecom",\n    "banque centrale populaire",  # BCP\n    "attijariwafa bank",\n    "managem",\n    "lafargeholcim maroc",\n    "label vie",\n    "ciments du maroc",\n    # ... complétez avec vos 16-20 sociétés\n]\n\n# Nombre max de pages à parcourir. La pagination Drupal démarre à page=0.\n# D\'après l\'exploration manuelle, il y a ~425 pages (page=0 à page=424 environ).\nMAX_PAGES = 425\n\nHEADERS = {\n    "User-Agent": (\n        "Mozilla/5.0 (compatible; RechercheAcademique/1.0; "\n        "usage stage universitaire, contact: <votre-email>)"\n    )\n}\n\nREQUEST_DELAY_SECONDS = 1.5  # politesse envers le serveur AMMC\nTIMEOUT = 20\n\n\n@dataclass\nclass RapportBrut:\n    societe: str\n    annee: str\n    type_rapport: str\n    url_fiche: str\n    page_liste: int\n\n\n@dataclass\nclass RapportDetaille(RapportBrut):\n    url_pdf: str = ""\n    nom_fichier: str = ""\n    taille_annoncee: str = ""  # ex: "13.82 Mo", tel qu\'affiché par l\'AMMC\n\n\ndef matches_target_company(nom_societe: str) -> bool:\n    nom = nom_societe.strip().lower()\n    return any(cible.lower() in nom for cible in COMPANIES)\n\n\ndef fetch_page(url: str) -> BeautifulSoup | None:\n    try:\n        resp = requests.get(url, headers=HEADERS, timeout=TIMEOUT)\n        resp.raise_for_status()\n        return BeautifulSoup(resp.text, "html.parser")\n    except requests.RequestException as e:\n        print(f"  [ERREUR] {url} -> {e}")\n        return None\n\n\ndef parse_list_page(soup: BeautifulSoup, page_num: int) -> list[RapportBrut]:\n    """Extrait les lignes du tableau \'Liste des Etats Financiers\' d\'une page."""\n    results = []\n    table = soup.find("table")\n    if not table:\n        return results\n\n    for row in table.find_all("tr"):\n        cells = row.find_all("td")\n        if len(cells) < 3:\n            continue\n\n        # Colonne Emetteur : contient un lien vers la fiche + le nom de la société\n        cell_emetteur = cells[0] if len(cells) == 3 else cells[1]\n        cell_annee = cells[1] if len(cells) == 3 else cells[2]\n        cell_type = cells[2] if len(cells) == 3 else cells[3]\n\n        liens = cell_emetteur.find_all("a")\n        if not liens:\n            continue\n        nom_societe = liens[-1].get_text(strip=True)\n\n        if not matches_target_company(nom_societe):\n            continue\n\n        lien_type = cell_type.find("a")\n        if not lien_type:\n            continue\n\n        url_fiche = lien_type["href"]\n        if url_fiche.startswith("/"):\n            url_fiche = BASE_URL + url_fiche\n\n        results.append(\n            RapportBrut(\n                societe=nom_societe,\n                annee=cell_annee.get_text(strip=True),\n                type_rapport=lien_type.get_text(strip=True),\n                url_fiche=url_fiche,\n                page_liste=page_num,\n            )\n        )\n    return results\n\n\ndef step1_crawl_list() -> list[RapportBrut]:\n    """Parcourt toutes les pages de la liste globale et filtre par société."""\n    all_results: list[RapportBrut] = []\n\n    for page_num in range(MAX_PAGES):\n        url = f"{LIST_URL}?page={page_num}"\n        print(f"[Page {page_num}/{MAX_PAGES}] {url}")\n\n        soup = fetch_page(url)\n        if soup is None:\n            time.sleep(REQUEST_DELAY_SECONDS)\n            continue\n\n        page_results = parse_list_page(soup, page_num)\n        if page_results:\n            print(f"  -> {len(page_results)} rapport(s) pertinent(s) trouvé(s)")\n            all_results.extend(page_results)\n\n        time.sleep(REQUEST_DELAY_SECONDS)\n\n    return all_results\n\n\ndef parse_detail_page(soup: BeautifulSoup) -> dict:\n    """Extrait le lien PDF direct + la taille depuis une fiche (ex: cosumar-rfa-2023)."""\n    info = {"url_pdf": "", "nom_fichier": "", "taille_annoncee": ""}\n\n    # Sur ces fiches, la pièce jointe apparaît typiquement comme :\n    # "COSUMAR RFA 2023.pdf (13.82 Mo)" avec un lien <a href=".../file.pdf">\n    for a in soup.find_all("a", href=True):\n        href = a["href"]\n        if href.lower().endswith(".pdf"):\n            info["url_pdf"] = href if href.startswith("http") else BASE_URL + href\n            texte = a.get_text(strip=True)\n            info["nom_fichier"] = texte\n\n            # La taille du fichier n\'est PAS dans le même <span> que le lien :\n            # structure réelle observée sur AMMC :\n            #   <td>\n            #     <span class="file ..."><a href="...">NOM.pdf</a></span>\n            #     <span>(13.82 Mo)</span>\n            #     <br/>\n            #   </td>\n            # On remonte donc jusqu\'au <td> englobant et on cherche le motif\n            # "(xx.xx Mo)" / "(xx Ko)" dans tout son texte, pas seulement dans\n            # le parent direct du lien.\n            cell = a.find_parent("td") or a.parent\n            cell_text = cell.get_text(" ", strip=True) if cell else texte\n            taille_match = re.search(r"\\(([\\d.,]+\\s?(?:Mo|Ko|Go))\\)", cell_text)\n            if taille_match:\n                info["taille_annoncee"] = taille_match.group(1)\n            break  # on prend le premier PDF trouvé sur la fiche\n\n    return info\n\n\ndef step2_enrich_with_pdf_links(rapports: list[RapportBrut]) -> list[RapportDetaille]:\n    """Va chercher, pour chaque fiche trouvée, le lien PDF + métadonnées."""\n    enriched = []\n\n    for i, r in enumerate(rapports, 1):\n        print(f"[{i}/{len(rapports)}] Détail : {r.societe} - {r.annee} - {r.url_fiche}")\n        soup = fetch_page(r.url_fiche)\n        detail_info = parse_detail_page(soup) if soup else {}\n\n        enriched.append(\n            RapportDetaille(\n                **asdict(r),\n                url_pdf=detail_info.get("url_pdf", ""),\n                nom_fichier=detail_info.get("nom_fichier", ""),\n                taille_annoncee=detail_info.get("taille_annoncee", ""),\n            )\n        )\n        time.sleep(REQUEST_DELAY_SECONDS)\n\n    return enriched\n\n\ndef save_csv(rows: list, path: str):\n    if not rows:\n        print(f"Rien à sauvegarder dans {path}")\n        return\n    fieldnames = list(asdict(rows[0]).keys())\n    with open(path, "w", newline="", encoding="utf-8") as f:\n        writer = csv.DictWriter(f, fieldnames=fieldnames)\n        writer.writeheader()\n        for row in rows:\n            writer.writerow(asdict(row))\n    print(f"-> {len(rows)} lignes écrites dans {path}")\n\n\ndef main():\n    print("=== Étape 1 : parcours de la liste globale AMMC ===")\n    rapports_bruts = step1_crawl_list()\n    save_csv(rapports_bruts, "ammc_rapports_bruts.csv")\n\n    if not rapports_bruts:\n        print("Aucun rapport trouvé pour les sociétés ciblées. Vérifiez COMPANIES.")\n        return\n\n    print("\\n=== Étape 2 : récupération des liens PDF directs ===")\n    rapports_detailles = step2_enrich_with_pdf_links(rapports_bruts)\n    save_csv(rapports_detailles, "ammc_rapports_detailles.csv")\n\n    print("\\nTerminé. Vérifiez ammc_rapports_detailles.csv")\n\n\nif __name__ == "__main__":\n    main()\n',
}


def list_scripts() -> None:
    """Affiche les étapes historiques disponibles dans ce regroupement."""
    for script_name in sorted(SCRIPTS):
        print(script_name)


def run_script(script_name: str) -> None:
    """Exécute un script historique dans un espace de noms isolé."""
    normalized = script_name if script_name.endswith(".py") else f"{script_name}.py"
    if normalized not in SCRIPTS:
        choices = ", ".join(sorted(SCRIPTS))
        raise SystemExit(f"Script inconnu : {script_name}\nChoix disponibles : {choices}")

    previous_directory = Path.cwd()
    os.chdir(PROJECT_ROOT)
    namespace = {
        "__name__": "__main__",
        "__file__": str(PROJECT_ROOT / normalized),
        "__package__": None,
    }
    try:
        source = SCRIPTS[normalized]
        exec(compile(source, namespace["__file__"], "exec"), namespace)
    finally:
        os.chdir(previous_directory)


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Lister ou exécuter une étape historique regroupée."
    )
    parser.add_argument("script", nargs="?", help="Nom du script à exécuter.")
    parser.add_argument(
        "--list", action="store_true", help="Afficher les scripts disponibles."
    )
    args = parser.parse_args()

    if args.list or not args.script:
        list_scripts()
        return
    run_script(args.script)


if __name__ == "__main__":
    main()
